@startuml

class PlayerProfile {
  + targetPosition : string
}

class PlayerAttribute {
  + name : string
  + value : float
}

class Player {
  + name : string
}

class ScoutingAssignment {
  + status : string
}

class ScoutingReport {
  + pros : string
  + cons : string
  + recommendation : string
}

class LongList {
  + evaluationDate : date
}

class ShortList {}

class OfficialOffer {}

class Employee {}

class HeadCoach extends Employee {}

class Director extends Employee {}

class Scout extends Employee {}

class HeadScout extends Scout {}

PlayerProfile "1" *-- "* PlayerAttribute" PlayerAttribute
PlayerProfile "1" -- "*" Player
Player "1" -- "0..*" LongList
LongList "1" -- "1" HeadScout : evaluated by
ScoutingAssignment "1" -- "1" Player
ScoutingAssignment "1" -- "1" Scout
ScoutingAssignment "1" -- "0..1" ScoutingReport
ScoutingReport "*" -- "1" Player
ShortList "1" -- "*" Player
ShortList "1" -- "1" HeadCoach : decided by
ShortList "1" -- "1" HeadScout : decided by
OfficialOffer "1" -- "1" Player
OfficialOffer "1" -- "1" Director

@enduml

